function couldBeSticky(intended: string, typed: string): boolean {
  const runs = (s: string): [string, number][] => {
    const out: [string, number][] = [];
    for (const c of s) {
      if (out.length && out[out.length - 1][0] === c) out[out.length - 1][1]++;
      else out.push([c, 1]);
    }
    return out;
  };
  const a = runs(intended), b = runs(typed);
  if (a.length !== b.length) return false;
  for (let i = 0; i < a.length; i++) {
    if (a[i][0] !== b[i][0] || a[i][1] > b[i][1]) return false;
  }
  return true;
}

