class Solution:
    def couldBeSticky(self, intended: str, typed: str) -> bool:
        def runs(s):
            out = []
            for c in s:
                if out and out[-1][0] == c:
                    out[-1][1] += 1
                else:
                    out.append([c, 1])
            return out

        a, b = runs(intended), runs(typed)
        if len(a) != len(b):
            return False
        return all(x[0] == y[0] and x[1] <= y[1] for x, y in zip(a, b))

