function couldBeSticky(intended: string, typed: string): boolean {
  let i = 0;
  for (let j = 0; j < typed.length; j++) {
    if (i < intended.length && intended[i] === typed[j]) i++;
    else if (j > 0 && typed[j] === typed[j - 1]) continue;
    else return false;
  }
  return i === intended.length;
}

